\label{the main}
Let $B$ be any linear continuous operator acting in $\mathbb X$ such that $\sigma (B) \cap \Gamma \subset \{ 1\}$, and let $x:=(x(n))_{n=1}^\infty$ be a bounded solution of (\ref{eq}). Then,
\begin{equation}\label{100}
\lim_{n\to\infty} [x(n+1)-x(n)]=0.
\end{equation}

\label{lem 2}
 Assume that $\bar x$ is any point in $\mathbb Y$, and the complex function $g(\lambda
):= R(\lambda ,\bar S )\bar x$ has the point $\lambda = \xi_0\in \Gamma$ as an isolated singular point. Then, $\xi_0$ is either a removable singular point or a pole of first order.

Without loss of generality we may assume that $\xi_0=1$. Consider $\lambda $ in a
small neighborhood of $1$ in the complex plane. We will express
$\lambda =e^{z}$ with $|z|< \delta_0 $. Choose a small $\delta_0
>0$ such that if $|z|<\delta_0   $, then
\begin{equation}
\frac{1}{|1-|\lambda ||} \le \frac{2}{|\Re z|}.
\end{equation}
Notice that if $0<|z |<\delta _0$, then
\begin{equation}
\| R(\lambda ,\bar S)\bar x \| \le \frac{1}{|1-|\lambda ||} \| \bar
x\| \le \frac{2}{|\Re z|} \| \bar x\| .
\end{equation}
Set $f(z )= R(e^z ,\bar S)\bar x $ with $|z|<\delta_0$. Since $1$ is
a singular point of $\| R(\lambda ,\bar S)\bar x \|$, $0$ is a
singular point of $f(z)$ in $\{ |z|<\delta_0 \}$ . For each $n\in
\mathbb Z$ and $0<r<\delta_0$, we have
\begin{eqnarray*}
&&\| \frac{1}{2\pi i} \int_{|z |=r}  z   ^n \left(
1+\frac{ z  ^2}{r^2}\right) f(z)dz \| \\
&& \hspace{2cm} \le \frac{1}{2\pi} \int_{|z |=r} | z  ^n \left(
1+\frac{ z  ^2}{r^2}\right)|\cdot \| f(z)\|\cdot |dz | .
\end{eqnarray*}
If $z =re^{i\varphi}$, where $\varphi$ is real, then one has
\begin{eqnarray}
| z ^n \left( 1+\frac{ z ^2}{r^2}\right)| &=& r^n |1+e^{2i\varphi} |
 =  r^n | e^{-i\varphi}+e^{i\varphi}|\nonumber\\
 &=& r^n 2|cos \varphi|= 2r^{n-1}|\Re z|.
\end{eqnarray}
Therefore,
\begin{eqnarray}
| \frac{1}{2\pi i} \int_{|z |=r}  z ^n \left(
1+\frac{z^2}{r^2}\right) f(z)dz | &\le& \frac{1}{2\pi}
\int_{|z|=r}2r^{n-1} | \Re z | \frac{2}{|\Re  z|} \cdot |dz |
\nonumber \\
&=& \frac{2\cdot 2r^{n-1}}{2\pi} \int_{|z|=r}  |dz | \nonumber \\
&=&{4r^{n}} .\label{15}
\end{eqnarray}
Consider the Laurent series of $f(z )$ at $z =0$,
\begin{equation}\label{laurent exp}
f(z) = \sum_{n=-\infty}^{\infty} a_n z^n,
\end{equation}
where
\begin{equation}\label{laurent coeff}
a_n =\frac{1}{2\pi i} \int_{| z |=r} \frac{f(z)dz }{z ^{n+1}},\quad
n\in \mathbb Z .
\end{equation}
From (\ref{15}) it follows that
\begin{eqnarray*}
\| a_{-(n+1)} + r^{-2} a_{-(n+3)}\| &=& \| \frac{1}{2\pi i}\int_{|z
|=r}  z ^n f(z)dz
 + \frac{1}{2\pi i} \int_{|z |=r} \frac{ z ^{n+2}}{r^2}
f(z)dz \| \nonumber\\
&=&  \| \frac{1}{2\pi i} \int_{|z |=r}  z ^n \left(
1+\frac{ z ^2}{r^2}\right) f(z)dz \| \\
&\le& 4r^{n}.
\end{eqnarray*}
Therefore,
\begin{equation}\label{an}
\| r^2a_{-(n+1)} + a_{-(n+3)}\| \le 4r^{n+2}, \quad n\in \mathbb Z .
\end{equation}
 Letting
$r$ tend to $0$ in (\ref{an}), we come up with $a_{-k}=0$ for all $k
\ge 2$. This shows that $z=0$ is a removable singular point (when $a_{-1}=0$) or a pole of first order of $f(z )$. This yields that the complex function  $g(\lambda
):= R(\lambda ,\bar S )\bar x$ has $\lambda =1$ as a removable singular point or a pole of first
order. The lemma is proven.

\label{lem 3}
Let $\xi_0\in\Gamma$ be an isolated singular point of $g(\lambda )= R(\lambda ,\bar S)\bar x$ with a given $\bar x\in \mathbb Y$. Then, this singular point $\xi_0$ is removable provided that
\begin{equation}\label{erg}
\lim_{\lambda \downarrow \xi_0} (\lambda -\xi_0 )R(\lambda ,\bar S)\bar x =0 .
\end{equation}

\label{lem 1} Let $x:=(x(n))$ be a bounded solution of
equation (\ref{eq}). Then,
\begin{equation}
\sigma (x) \subset \sigma (B) \cap \Gamma .
\end{equation}

Consider $R(\lambda ,\bar S )\bar x$ for all $|\lambda |\not= 1$.
Since $x$ is a bounded solution of (\ref{eq}) and $\bar y=0$ we have
\begin{eqnarray}
 R(\lambda ,\bar S )\bar S \bar x&=&  R(\lambda ,\bar S )\bar B \bar x + R(\lambda ,\bar S ) \bar y \nonumber \\
&=& \bar B R(\lambda ,\bar S )\bar x \label{eq2}
\end{eqnarray}
On the other hand, the identity $ \lambda R(\lambda ,\bar S ) \bar x
-\bar x  =  R(\lambda ,\bar S )\bar S \bar x$ gives
\begin{equation}
\lambda R(\lambda ,\bar S ) \bar x -\bar x =  R(\lambda ,\bar S
)\bar S \bar x    =\bar B R(\lambda ,\bar S )\bar x,
\end{equation}
so,
\begin{eqnarray*}
\bar x &=& \lambda R(\lambda ,\bar S ) \bar x - \bar B R(\lambda ,\bar S )\bar x \\
&=& (\lambda   - \bar B ) R(\lambda ,\bar S )\bar x .\\
\end{eqnarray*}
Obviously, $R(\lambda ,\bar S )\bar x$ is analytic on $\mathbb C \backslash
\Gamma$. Moreover, if $|\xi_1 |=1$ and $\xi_1\not\in \sigma (B)\cap
\Gamma$, (as we can easily check that $\sigma (\bar B )=\sigma
(B)$), in a small neighborhood $U(\xi_1 )$ of $\xi_1$ we have
\begin{eqnarray}\label{eq3}
R(\lambda ,\bar S )\bar x &=& (\lambda   - \bar B )^{-1} \bar x
,\quad \lambda \in U(\xi_1)\backslash \Gamma .
\end{eqnarray}
This shows that $g(\lambda ) = R(\lambda ,\bar S )\bar x $ is
analytically extendable to a neighborhood of $\xi_1$, that is,
$\xi_1 \not\in \sigma (x)$. The lemma is proven.

The identity $R(\lambda ,\bar S)\bar
S\bar x = \lambda R(\lambda , \bar S)\bar x - \bar x$ gives
\begin{eqnarray*}
 R(\lambda ,\bar S)(\bar S \bar x -\bar x ) &=& R(\lambda ,\bar S)\bar S \bar x-R(\lambda ,\bar S) \bar x \\
 &=& \lambda R(\lambda , \bar S)\bar x - \bar x -R(\lambda ,\bar S) \bar x    \\
 &=& (\lambda -1 )R(\lambda ,\bar S)  \bar x -\bar x .
\end{eqnarray*}
Therefore,
\begin{eqnarray}\label{eq8}
h(\lambda ):= (\lambda -1) R(\lambda ,\bar S)(\bar S \bar x -\bar x
) &=& (\lambda -1 )^2 R(\lambda ,\bar S)  \bar x -(\lambda
-1)\bar x .
\end{eqnarray}
By Lemmas \ref{lem 1}, \ref{lem 2}, $\sigma (Sx-x) \subset \sigma
(B)\cap \Gamma \subset \{ 1\}$, $h(\lambda )$ is extendable
analytically to the whole complex plane with only possible exception
at $1$. Since $g(\lambda ): = R(\lambda ,\bar S) \bar x$ has $1$ as
a either removable singular point or a pole of first order we have
\begin{eqnarray*}
 \lim_{\lambda \to 1} (\lambda -1)^2 R(\lambda ,\bar S) \bar x   &=&  0.
\end{eqnarray*}
Consequently,
\begin{eqnarray*}
 \lim_{\lambda \to 1} (\lambda -1) R(\lambda ,\bar S)(\bar S \bar x -\bar x ) &=&   \lim_{\lambda \to 1} [ (\lambda -1 )^2 R(\lambda ,\bar S) \bar x -(\lambda -1)\bar x
 ]\\
 &=&    \lim_{\lambda \to 1}   (\lambda -1 )^2 R(\lambda ,\bar S) \bar x -\lim_{\lambda \to 1} (\lambda -1)\bar x \\
 &=& 0.
\end{eqnarray*}
By Lemma \ref{lem 3}, $h(\lambda)$ has $\lambda =1$ as a removable
singular point, so $h(\lambda )$ is extendable to an entire
function. For $|\lambda |>1$, by (\ref{112})
we have
\begin{eqnarray*}
\limsup_{|\lambda|\to\infty} \| h(\lambda )\| &=&  \limsup_{|\lambda|\to\infty} \| (\lambda -1) R(\lambda ,\bar S)(\bar S \bar x -\bar x )\| \nonumber\\
 &\le& \limsup_{|\lambda|\to\infty}  \frac{|\lambda |+1}{  |\lambda |-1 } \cdot \| \bar S \bar x -\bar x \|  \nonumber\\
 &=& \| \bar S \bar x -\bar x \| .\label{eq9}
\end{eqnarray*}
This shows that $h(\lambda )$ is bounded on the complex plane, so,
as a bounded entire function it should be a constant by Liouville's
Theorem. In turn, it is identically equal to zero because $h(1
):=\lim_{\lambda \to 1}h(\lambda )=0$. Since $R(\lambda ,\bar S)$ is
injective for each $\lambda \not= 1$, we have $\bar S\bar x-\bar
x=0$. Therefore, $(Sx-x)\in c_0$, that is, (\ref{100}). The theorem
is proven.
\begin{remark}
In the remark following Theorem \ref{the tec} we will give an alternative proof of Theorem \ref{the main} in a more general context. However, the above proof seems to be more elementary.
\end{remark}

\label{lem 4} Let $x:=(x(n))\in l^\infty (\mathbb X )$. Then, the following assertions hold:
\begin{enumerate}
\item $\sigma (x)=\emptyset$ if and only if $x\in c_0$;
\item If $\sigma (\bar x) \not= \emptyset$, then
  $\sigma (x)=\sigma ( \bar S |_{{\mathcal M}_{\bar x}})$.
\end{enumerate}

\label{the tec}
Let $(x(n))$ be a bounded sequence such that the set $\sigma ( x)$ of
all non-removable singular points of $g(\lambda )=R(\lambda ,\bar
S)\bar x$ is countable, and let the following condition holds for
each $\xi_0\in \sigma (\bar x)$
\begin{equation}
\lim_{\lambda \downarrow \xi_0} (\lambda -\xi_0 )R(\lambda ,\bar
S)\bar x =0 .
\end{equation}
Then, \begin{equation}\label{55} \lim_{n\to\infty}x(n)=0.
\end{equation}

\label{the main2}
For equation (\ref{eq}) assume that $(y(n))\in c_0$, and the operator $B$ in equation (\ref{eq}) has $\sigma (B)\cap \Gamma$ as a countable set. Then, the following holds for each bounded solution $(x(n))$ of (\ref{eq})
\begin{equation}
\lim_{n\to\infty} x(n)=0,
\end{equation}
provided that for each $\xi_0 \in \sigma (B)\cap \Gamma$ the following condition holds
\begin{equation}\label{min}
\lim_{\lambda  \downarrow \xi_0} (\lambda -\xi_0)R(\lambda , \bar
S)\bar x =0 .
\end{equation}

Let $T$ be a power bounded linear operator in a Banach space $\mathbb X$ such that $\sigma (T)\cap \Gamma \subset \{ 1\}$. Then,
\begin{equation}\label{kt2}
\lim_{n\to\infty} (T^{n+1}-T^n )=0.
\end{equation}

\label{the vu}
Let $T$ be a power bounded linear operator in a Banach space $\mathbb X$
such that $\sigma (T)\cap \Gamma \subset \{ 1\}$. Then, for each
$x_0\in\mathbb X$
\begin{equation}\label{kt}
\lim_{n\to\infty} (T^{n+1}x_0-T^n x_0)=0.
\end{equation}

\label{lem 3.3}
Let $B\in L(\mathbb X)$ be a power bounded operator such that $\sigma (B)\cap \Gamma$ is a countable set.
Moreover, assume that for each $\xi_0\in \sigma (B)\cap \Gamma$ the following holds for each $x_0\in \mathbb X$
\begin{equation}\label{con b}
\lim_{\lambda  \downarrow \xi_0} (\lambda -\xi_0 )R(\lambda ,  B)x_0 =0 .
\end{equation}
Then, for every $x_0\in\mathbb X$
\begin{equation}
\lim_{n\to\infty} B^nx_0=0 .
\end{equation}

\label{the tec2}
Let $(x(n))$ be a bounded sequence such that the set
$\sigma_{AAP(\mathbb N,\mathbb X)} ( x)$ of all non-removable singular points of
$g(\lambda )=R(\lambda ,\bar S)\bar x$ is countable, and let the
following condition hold for each $\xi_0\in \sigma_{AAP(\mathbb N,\mathbb X)} ( x)$
\begin{equation}
\lim_{\lambda \downarrow \xi_0} (\lambda -\xi_0 )R(\lambda ,\bar
S)\bar x =0 .
\end{equation}
Then, $(x(n))$ is asymptotically almost periodic.

\label{the main7}
For equation (\ref{eq}) assume that $(y(n))\in AAP(\mathbb N,\mathbb X)$, and the
operator $B$ in equation (\ref{eq}) has $\sigma (B)\cap \Gamma$ as a
countable set. Then, each bounded solution $(x(n))$ of (\ref{eq}) is
asymptotically almost periodic, provided that for each $\xi_0 \in
\sigma (B)\cap \Gamma$ the following holds
\begin{equation}\label{min6}
\lim_{\lambda \downarrow \xi_0} (\lambda -\xi_0)R(\lambda , \bar
S)\bar x =0 .
\end{equation}
